#!/bin/bash
# Write the images generated by a603-build-image.sh to the board (Seeed A603 + Jetson Orin NX).
# This is the only step that uses the board over USB.
# The recovery USB link must be 480 Mbps when this starts.
#
# The NVMe SSD is not visible from the PC. l4t_initrd_flash.sh boots the board into a small
# Linux (initrd), and the board itself finds nvme0n1, writes the GPT from
# flash_l4t_t234_nvme.xml and writes the partitions. This script checks the result in the log.
#
# Usage, with W7 pin 3 (FORCE_RECOVERY) shorted to pin 4 (GND) and the SSD in the M.2 Key M slot before power-on:
#   a603-flash-image.sh [-w DIR] [--erase]
#     -w DIR   work directory used by a603-build-image.sh
#              (default: WORK_DIR, else the current directory)
#     --erase  erase every storage device (whole SSD and QSPI) before writing
#              (l4t_initrd_flash.sh --erase-all). Use it for an SSD that held another system.
# The full log is saved to flash-image.log in the work directory.

set -euo pipefail

TARGET="jetson-orin-nano-devkit-super"
WORK_DIR="${WORK_DIR:-$(pwd)}"
erase=0
args=("$@")
while [[ $# -gt 0 ]]; do
	case "$1" in
		-w) WORK_DIR="${2:?-w needs a directory}"; shift ;;
		--erase) erase=1 ;;
		-h|--help) sed -n '2,17p' "$0"; exit 0 ;;
		*) echo "unknown option: $1" >&2; exit 2 ;;
	esac
	shift
done

WORK_DIR="$(cd "$WORK_DIR" && pwd)"
L4T="${WORK_DIR}/Linux_for_Tegra"
LOG="${WORK_DIR}/flash-image.log"

if [[ ! -f "${L4T}/tools/kernel_flash/images/external/system.img" ]]; then
	echo "Flash images are missing in ${L4T}." >&2
	echo "Run a603-build-image.sh -w ${WORK_DIR} first, or pass the right directory with -w." >&2
	exit 1
fi

if [[ "$(id -u)" -ne 0 ]]; then
	exec sudo WORK_DIR="$WORK_DIR" bash "$0" "${args[@]}"
fi

exec > >(tee "$LOG") 2>&1
cd "$L4T"
echo 2048 > /sys/module/usbcore/parameters/usbfs_memory_mb
echo -1 > /sys/module/usbcore/parameters/autosuspend

apx_dir=""
apx_speed=""
for vendor in /sys/bus/usb/devices/*/idVendor; do
	[[ -f "$vendor" ]] || continue
	[[ "$(cat "$vendor")" == "0955" ]] || continue
	dir="$(dirname "$vendor")"
	prod="$(cat "${dir}/idProduct")"
	case "$prod" in
		7323|7423|7523|7623)
			apx_dir="$dir"
			apx_speed="$(cat "${dir}/speed")"
			echo on > "${dir}/power/control" 2>/dev/null || true
			echo -1 > "${dir}/power/autosuspend_delay_ms" 2>/dev/null || true
			echo "Found NVIDIA APX 0955:${prod} at $(basename "$dir") speed=${apx_speed}"
			break
			;;
	esac
done

if [[ -z "$apx_dir" || "$apx_speed" != "480" ]]; then
	echo "Need a 480 Mbps recovery device before flashing. speed=${apx_speed:-missing}" >&2
	lsusb -t || true
	exit 1
fi

erase_opt=()
if [[ "$erase" -eq 1 ]]; then
	erase_opt=(--erase-all)
	echo "Erasing every storage device on the board (whole SSD and QSPI) before writing."
fi
echo "The NVMe SSD must have been in the M.2 Key M slot before power-on (no hot-plug)."

# Logs l4t_initrd_flash.sh copies back from the board, to find the one from this run.
mkdir -p initrdlog
touch "${WORK_DIR}/.flash-start"

status=0
./tools/kernel_flash/l4t_initrd_flash.sh \
	--flash-only \
	"${erase_opt[@]}" \
	--external-device nvme0n1p1 \
	-c tools/kernel_flash/flash_l4t_t234_nvme.xml \
	-p "-c bootloader/generic/cfg/flash_t234_qspi.xml" \
	--showlogs \
	--network usb0 \
	"$TARGET" \
	internal || status=$?

board_log="$(find initrdlog -type f -newer "${WORK_DIR}/.flash-start" 2>/dev/null | sort | tail -n 1)"
rm -f "${WORK_DIR}/.flash-start"

echo
if [[ "$status" -ne 0 ]]; then
	echo "Flash failed (l4t_initrd_flash.sh exit ${status})." >&2
	if grep -qiE 'nvme0n1.*(not found|no such|cannot|fail)|(cannot|could not|unable to) find.*nvme' \
		"$LOG" ${board_log:+"$board_log"} 2>/dev/null; then
		echo "The board did not find the NVMe SSD (nvme0n1):" >&2
		echo "  - power off, seat the SSD in the M.2 Key M slot (M.2 2280 NVMe, not SATA), power on in REC" >&2
		echo "  - try another SSD if it still is not found" >&2
	fi
	echo "Full log: ${LOG}${board_log:+, board log: ${L4T}/${board_log}}" >&2
	exit "$status"
fi

if ! grep -qiE 'flash(ing)? (is )?success' "$LOG"; then
	echo "l4t_initrd_flash.sh ended without error but no success message was found." >&2
	echo "Check ${LOG}${board_log:+ and ${L4T}/${board_log}} before booting." >&2
	exit 1
fi

if [[ -n "$board_log" ]]; then
	echo "Board log: ${L4T}/${board_log}"
fi
echo "Flash finished. Power off, remove the W7 pin 3-4 short, then power on."
